// Minimal Node.js Azure Function skeleton
module.exports = async function (context, req) {
  const { tenantId } = req.params;
  if (!/^[a-zA-Z0-9_-]+$/.test(tenantId)) {
    context.res = { status: 400, body: 'Invalid tenantId' };
    return;
  }
  const payload = req.body;
  if (!payload || JSON.stringify(payload).length > 1024) {
    context.res = { status: 400, body: 'Invalid payload size' };
    return;
  }
  // compute hash (pseudo)
  const crypto = require('crypto');
  const hash = crypto.createHash('sha256').update(JSON.stringify(payload)).digest('hex');
  const ts = new Date().toISOString();
  // write to Cosmos DB (partitionKey=tenantId, id=hash)
  // write to Blob Storage at telemetry/{tenantId}/{YYYY/MM/DD}/{hash}.json
  context.res = { status: 202, body: 'accepted' };
};
```

