## Why This Is Asked

Explores a beginner-friendly, real-world pattern for event-driven cloud applications using Azure Functions, Storage Queues, and Cosmos DB with per-tenant isolation. Emphasizes idempotent processing, observability, and robust retry logic.

## Key Concepts

- Azure Functions (HTTP trigger and Queue trigger)
- Cosmos DB partitioning by tenantId
- Azure Storage Queue semantics and poison messages
- Blob Storage for produced assets
- Retries with exponential backoff and observability with Application Insights

## Code Example

```javascript
// Pseudo-idempotent processing sketch
module.exports = async function (context, queueMessage) {
  const { tenantId, jobId, imageUrl } = queueMessage;

  // Check idempotency - skip if already processed
  const existingJob = await cosmosDB.readJob(tenantId, jobId);
  if (existingJob && existingJob.status === 'completed') {
    context.log.info(`Job ${jobId} already completed, skipping`);
    return;
  }

  try {
    // Update status to processing
    await cosmosDB.updateJobStatus(tenantId, jobId, 'processing');

    // Process image
    const resizedImage = await imageProcessor.resize(imageUrl);

    // Store result in tenant-specific blob path
    const blobUrl = await blobStorage.upload(
      `tenants/${tenantId}/processed/${jobId}.jpg`,
      resizedImage
    );

    // Mark as completed
    await cosmosDB.updateJobStatus(tenantId, jobId, 'completed', blobUrl);

  } catch (error) {
    // Log error and update status
    context.log.error(`Failed to process job ${jobId}:`, error);
    await cosmosDB.updateJobStatus(tenantId, jobId, 'failed', null, error.message);
    throw error; // Re-throw for queue retry
  }
};
```

## Implementation Notes

- **Data Models**: Cosmos DB document with tenantId partition key, jobId, status, and metadata
- **Isolation**: Tenant-specific blob paths and Cosmos DB queries ensure data separation
- **Idempotency**: Job status check prevents duplicate processing
- **Observability**: Application Insights tracks function execution and errors
- **Retry Strategy**: Built-in queue retries with exponential backoff for transient failures

## Why This Is Asked

This question assesses the ability to design a low-latency, highly available, and auditable per-tenant feature-flag system using Azure-native services. It tests understanding of cache invalidation strategies, security patterns, and multi-tenant isolation in a distributed system.

## Key Concepts

- **Azure App Configuration** serves as the source of truth, with per-tenant configuration sections or separate stores for tenant isolation
- **Azure Redis Cache** provides sub-millisecond reads with TTL-based expiration and stale-while-revalidate patterns for high availability
- **Azure Functions** with Managed Identity (MSI) and Azure AD authentication eliminate secrets management and enable secure, tenant-aware access
- **Event-driven cache invalidation** via Event Grid or Service Bus pub/sub ensures consistency across cache nodes
- **Cosmos DB** stores immutable audit logs with tenant-scoped partition keys for compliance and traceability
- **RBAC and Private Endpoints** enforce strict data-plane isolation and network security per tenant

## Code Example

```javascript
async function getFlag(tenantId, flagName, { cache, appConfig, logger }) {
  const cacheKey = `${tenantId}:${flagName}`;

  let flag = await cache.get(cacheKey);
  if (flag !== undefined) return flag;

  try {
    flag = await appConfig.get({ key: `${tenantId}/${flagName}` });
    await cache.set(cacheKey, flag, { TTL: 30 });
  } catch (err) {
    logger.warn('Flag fetch failed, checking stale cache', { tenantId, flagName });
    flag = await cache.getStale(cacheKey);
    if (!flag) throw err;
  }

  return flag;
}
```

## Why This Is Asked
Tests practical use of per-tenant data isolation, cache strategy, and basic Azure services integration in a beginner-friendly task.

## Key Concepts
- Azure Functions HTTP trigger with route parameters
- Azure Redis Cache: TTL-based caching and error handling
- Cosmos DB: PartitionKey per tenant for isolation with retry logic
- Azure App Configuration for per-tenant feature/data with fallbacks
- Graceful degradation and circuit breaker patterns

## Code Example
```javascript
const { CosmosClient } = require('@azure/cosmos');
const { AppConfigurationClient } = require('@azure/app-configuration');
const redis = require('redis');

module.exports = async function (context, req) {
  const tenantId = req.headers['x-tenant-id'] || req.params.tenantId;
  const productId = req.params.productId;
  const cacheKey = `pricing:${tenantId}:${productId}`;

  try {
    // Check Redis cache first
    const cached = await getCachedPrice(cacheKey);
    if (cached) {
      return { status: 200, body: cached };
    }

    // Cache miss - fetch from Cosmos DB
    const basePrice = await fetchBasePrice(tenantId, productId);

    // Get discount from App Config with fallback
    const discount = await fetchDiscount(tenantId);

    // Calculate final price
    const finalPrice = basePrice.price * (1 - discount);
    const result = {
      price: finalPrice,
      currency: basePrice.currency || 'USD',
      discountApplied: discount
    };

    // Cache result for 60s
    await setCachedPrice(cacheKey, result, 60);

    return { status: 200, body: result };

  } catch (error) {
    context.log.error('Pricing endpoint error:', error);
    return { 
      status: 500, 
      body: { error: 'Unable to fetch pricing information' } 
    };
  }
};

async function getCachedPrice(key) {
  try {
    const client = redis.createClient(process.env.REDIS_CONNECTION_STRING);
    const cached = await client.get(key);
    return cached ? JSON.parse(cached) : null;
  } catch (error) {
    console.error('Redis cache read failed:', error);
    return null; // Continue without cache
  }
}

async function setCachedPrice(key, value, ttlSeconds) {
  try {
    const client = redis.createClient(process.env.REDIS_CONNECTION_STRING);
    await client.setEx(key, ttlSeconds, JSON.stringify(value));
  } catch (error) {
    console.error('Redis cache write failed:', error);
    // Continue without caching
  }
}

async function fetchBasePrice(tenantId, productId) {
  const client = new CosmosClient(process.env.COSMOS_CONNECTION_STRING);
  const container = client.database('catalog').container('products');

  try {
    const { resource } = await container.item(productId, tenantId).read();
    if (!resource) throw new Error('Product not found');
    return resource;
  } catch (error) {
    // Fallback to default pricing structure
    return { price: 100.0, currency: 'USD' };
  }
}

async function fetchDiscount(tenantId) {
  const client = new AppConfigurationClient(process.env.APP_CONFIG_CONNECTION_STRING);

  try {
    const { value } = await client.getConfigurationSetting(
      { key: `pricing:discount:${tenantId}` }
    );
    return parseFloat(value) || 0;
  } catch (error) {
    try {
      // Fallback to global discount
      const { value } = await client.getConfigurationSetting(
        { key: 'pricing:discount:global' }
      );
      return parseFloat(value) || 0;
    } catch (globalError) {
      return 0; // No discount available
    }
  }
}
```

